/* =========================================
   DESKTOP LAYOUT (Full-Width / Stretched)
   ========================================= */

/* TIGHTENED: Reduced bottom margin to pull content up */
.dashboard-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 1rem !important; 
}

.management-container {
    width: 100%;
    max-width: none; 
    margin: 0;
    /* TIGHTENED: Reduced top padding from 1.5rem to 0.2rem */
    padding: 0.2rem 0 1.5rem 0; 
    color: #f8fafc;
    /* animation: slideUpFade 0.5s ease-out; */
}

/* Header Tweaks */
.management-header h1 {
    font-size: 2rem;
    font-weight: 800;
    letter-spacing: -0.025em;
    margin-bottom: 0.25rem;
}

/* --- Code Generator Card --- */
.code-generator-card {
    position: relative;
    width: 100%;
    box-sizing: border-box; 
    overflow: hidden;
    transition: all 0.3s ease;
    background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%);
    padding: 30px; 
    border-radius: 12px; 
    margin-top: 0; /* Ensures no extra gap above the card */
    margin-bottom: 30px;
    border: 1px solid #334155;
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
}

.code-generator-card::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 4px;
    height: 100%;
    background: #3b82f6; 
}

.code-flex-row {
    display: flex;
    align-items: center;
    gap: 20px;
}

.code-display-box {
    background: #020617; 
    padding: 14px 28px; 
    border-radius: 8px; 
    border: 1px dashed #3b82f6; 
    color: #60a5fa; 
    font-family: 'JetBrains Mono', 'Courier New', monospace; 
    font-weight: 700; 
    font-size: 1.6rem;
    letter-spacing: 4px;
    box-shadow: inset 0 2px 10px rgba(0,0,0,0.5);
    display: inline-block;
}

/* --- Table Styles --- */
.table-container {
    width: 100%;
    box-sizing: border-box;
    background: #0f172a;
    border-radius: 16px;
    border: 1px solid #1e293b;
    box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.2);
    margin-top: 1rem;
    overflow: hidden;
}

.management-table {
    width: 100%;
    border-collapse: collapse;
}

.management-table th {
    background: rgba(30, 41, 59, 0.5);
    padding: 1.25rem 1.5rem;
    color: #64748b;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    text-align: left;
}

.management-table td {
    padding: 1.25rem 1.5rem;
    border-bottom: 1px solid #1e293b;
    color: #e2e8f0;
    vertical-align: middle;
}

.management-table tr:hover {
    background: rgba(59, 130, 246, 0.03); 
}

/* Personnel Info Styling */
.user-info {
    display: flex;
    align-items: center;
    gap: 12px;
}

.user-initial {
    width: 32px;
    height: 32px;
    background: #3b82f6;
    color: white;
    border-radius: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
    font-weight: 700;
    font-size: 0.85rem;
}

