const { chromium } = require('playwright');
const fs = require('fs');

const BASE = 'http://localhost:5174';
const token = fs.readFileSync(__dirname + '/token.txt', 'utf8').trim();

(async () => {
  const browser = await chromium.launch({ channel: 'msedge', headless: true });
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 } });
  const page = await ctx.newPage();
  const log = (m) => console.log('STEP:', m);

  // Inject auth before app boots
  await ctx.addInitScript(([t]) => {
    localStorage.setItem('accessToken', t);
    localStorage.setItem('userRole', 'FM');
    localStorage.setItem('userName', 'System Root Admin');
    localStorage.setItem('userId', '1');
  }, [token]);

  page.on('console', (msg) => { if (msg.type() === 'error') console.log('CONSOLE ERROR:', msg.text()); });
  page.on('pageerror', (err) => console.log('PAGE ERROR:', err.message));

  // ---- Incident dashboard @1280 ----
  await page.goto(BASE + '/incidents', { waitUntil: 'networkidle' });
  await page.waitForSelector('.inc-table tbody tr', { timeout: 15000 });
  log('h1 = ' + (await page.textContent('.dashboard-header h1')).trim());
  log('card labels = ' + JSON.stringify(await page.$$eval('.inc-stat-label', els => els.map(e => e.textContent.trim()))));
  log('header buttons = ' + JSON.stringify(await page.$$eval('.inc-header-actions button', els => els.map(e => e.textContent.trim()))));
  log('sidebar links = ' + JSON.stringify(await page.$$eval('.sidebar-nav a', els => els.map(e => e.textContent.trim()))));
  log('first timestamp cell HTML = ' + await page.$eval('.inc-table tbody tr td:first-child', e => e.innerHTML.trim()));

  // table overflow state at 1280
  const geom = (await page.$eval('.inc-table-wrap', el => ({
    clientWidth: el.clientWidth, scrollWidth: el.scrollWidth,
  })));
  log('table-wrap @1280 = ' + JSON.stringify(geom));

  // ACTIONS th center vs button group center
  const centers = await page.evaluate(() => {
    const th = document.querySelector('.inc-table th:last-child');
    const grp = document.querySelector('.inc-table tbody tr .action-button-group');
    const cell = document.querySelector('.inc-table tbody tr .actions-cell');
    const r = (x) => { const b = x.getBoundingClientRect(); return { left: b.left, right: b.right, cx: (b.left + b.right) / 2, w: b.width }; };
    return { th: r(th), group: r(grp), cell: r(cell) };
  });
  log('centers = ' + JSON.stringify(centers));

  await page.screenshot({ path: __dirname + '/incidents-1280.png', fullPage: false });

  // ---- narrow: 1024 laptop, scroll table fully right ----
  await page.setViewportSize({ width: 1024, height: 768 });
  await page.waitForTimeout(400);
  const geom2 = await page.$eval('.inc-table-wrap', el => { el.scrollLeft = el.scrollWidth; return { clientWidth: el.clientWidth, scrollWidth: el.scrollWidth }; });
  log('table-wrap @1024 = ' + JSON.stringify(geom2));
  await page.waitForTimeout(300);
  await page.screenshot({ path: __dirname + '/incidents-1024-scrolled.png', fullPage: false });

  // mid-scroll state (sticky visible over other columns)
  await page.$eval('.inc-table-wrap', el => { el.scrollLeft = Math.max(0, (el.scrollWidth - el.clientWidth) / 2); });
  await page.waitForTimeout(300);
  const centers2 = await page.evaluate(() => {
    const th = document.querySelector('.inc-table th:last-child');
    const grp = document.querySelector('.inc-table tbody tr .action-button-group');
    const r = (x) => { const b = x.getBoundingClientRect(); return { cx: Math.round((b.left + b.right) / 2), w: Math.round(b.width), left: Math.round(b.left), right: Math.round(b.right) }; };
    return { th: r(th), group: r(grp) };
  });
  log('centers @1024 mid-scroll = ' + JSON.stringify(centers2));
  await page.screenshot({ path: __dirname + '/incidents-1024-midscroll.png', fullPage: false });

  // ---- navigate via Support Tickets button ----
  await page.setViewportSize({ width: 1280, height: 800 });
  await page.click('.inc-support-btn');
  await page.waitForURL('**/support-dashboard');
  await page.waitForSelector('.sup-stats-grid', { timeout: 10000 });
  log('support h1 = ' + (await page.textContent('.dashboard-header h1')).trim());
  log('support cards = ' + JSON.stringify(await page.$$eval('.sup-stat-card', els => els.map(e => e.textContent.trim()))));
  await page.screenshot({ path: __dirname + '/support-tickets-tab.png', fullPage: false });

  // KB tab: cards must disappear
  await page.click('.support-tab:has-text("Knowledge Base")');
  await page.waitForTimeout(600);
  const kbCards = await page.$$('.sup-stats-grid');
  log('cards on KB tab = ' + kbCards.length);
  await page.screenshot({ path: __dirname + '/support-kb-tab.png', fullPage: false });

  // ---- back button ----
  await page.click('.sup-back-btn');
  await page.waitForURL('**/incidents');
  log('back nav OK, url = ' + page.url());

  await browser.close();
  console.log('DONE');
})().catch((e) => { console.error('FATAL:', e); process.exit(1); });

